using AcxiomCRM.Data;using AcxiomCRM.Models;using AcxiomCRM.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers;
[Authorize] public class OpportunitiesController(ApplicationDbContext db,AuditService audit):Controller{
 public async Task<IActionResult>Index(){var q=db.Opportunities.Include(x=>x.Customer).Include(x=>x.Owner).AsQueryable();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager"))q=q.Where(x=>x.OwnerId==User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value);return View(await q.OrderBy(x=>x.ExpectedCloseDate).ToListAsync());}
 public async Task<IActionResult>Create(){var customers=db.Customers.AsQueryable();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager")){var uid=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value;customers=customers.Where(x=>x.OwnerId==uid);}ViewBag.Customers=await customers.OrderBy(x=>x.Name).ToListAsync();return View(new Opportunity());}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(Opportunity m){if(m.Stage!="Won"&&m.Stage!="Lost"&&m.ExpectedCloseDate.Date<DateTime.Today)ModelState.AddModelError(nameof(m.ExpectedCloseDate),"Expected Close Date cannot be in the past.");if(m.Amount<=0)ModelState.AddModelError(nameof(m.Amount),"Opportunity Amount must be greater than 0.");
 if(m.Probability<0||m.Probability>100)ModelState.AddModelError(nameof(m.Probability),"Probability must be between 0 and 100.");
 var currentUserId=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value;
 var customerAllowed=await db.Customers.AnyAsync(c=>c.Id==m.CustomerId&&(User.IsInRole("Admin")||User.IsInRole("Manager")||c.OwnerId==currentUserId));
 if(!customerAllowed)ModelState.AddModelError(nameof(m.CustomerId),"Select a customer you are allowed to access.");if(!ModelState.IsValid){var customers=db.Customers.AsQueryable();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager")){var uid=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value;customers=customers.Where(x=>x.OwnerId==uid);}ViewBag.Customers=await customers.ToListAsync();return View(m);}m.OwnerId=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value;db.Opportunities.Add(m);await db.SaveChangesAsync();await audit.WriteAsync(User,"Opportunities","Create",m.Id.ToString(),m.Name);TempData["Success"]="Opportunity created.";return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Stage(int id,string stage){var x=await db.Opportunities.FindAsync(id);if(x==null)return NotFound();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager")&&x.OwnerId!=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value)return Forbid();if(!new[]{"Qualification","Proposal","Negotiation","Won","Lost"}.Contains(stage))return BadRequest();x.Stage=stage;if(stage=="Won")x.Probability=100;if(stage=="Lost")x.Probability=0;await db.SaveChangesAsync();await audit.WriteAsync(User,"Opportunities","StageChanged",id.ToString(),stage);return RedirectToAction(nameof(Index));}
}
